<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/database/cli.php';require_once BASE_PATH.'/app/Models/ShoppingModel.php';require_once BASE_PATH.'/app/Models/OrderModel.php';
try{$options=migrationOptions();if(!preg_match('/^tecno_star_test_catalog_[a-zA-Z0-9_]{1,16}$/D',$options['database']))throw new RuntimeException('Solo datos sintéticos.');$db=migrationConnection($options);$buyer=(int)$db->query("SELECT id_usuario FROM tbusuarios WHERE correo='client@catalog.example.test'")->fetchColumn();$actor=(int)$db->query("SELECT id_usuario FROM tbusuarios WHERE correo='admin@catalog.example.test'")->fetchColumn();$product=(int)$db->query("SELECT id_producto FROM tbproductos WHERE codigo_producto='CAT-001'")->fetchColumn();$shop=new ShoppingModel($db);foreach($shop->state($buyer)['cart'] as $item)$shop->mutate($buyer,['action'=>'cart_remove','product_id'=>$item['id']]);$shop->mutate($buyer,['action'=>'cart_add','product_id'=>$product,'quantity'=>1]);$model=new OrderModel($db);$order=$model->create($buyer,['solicitud'=>bin2hex(random_bytes(32)),'cotizacion'=>$model->quote($buyer)['fingerprint'],'nombre'=>'Vista de caja','telefono'=>'70000000','correo'=>'preview@example.test','acepto'=>'1']);$state='pendiente';foreach((in_array('--confirmed',$argv,true)?['confirmado']:['confirmado','en_preparacion','listo']) as $target){$order=$model->transition($actor,(int)$order['id_pedido'],$target,$state,'Preparación de vista sintética');$state=$target;}echo 'Pedido sintético '.$order['estado'].': '.$order['codigo_pedido']."\n";}catch(Throwable $error){fwrite(STDERR,$error->getMessage()."\n");exit(1);}
